import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"AI Assistant — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"AI Assistant — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/ai-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"AI Assistant — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/ai-production-readiness"}]]},"headers":[],"relativePath":"deployment/ai-production-readiness.md","filePath":"deployment/ai-production-readiness.md","lastUpdated":1787680328000}'),r={name:"deployment/ai-production-readiness.md"};function s(i,t,n,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="ai-assistant-—-production-readiness-audit" tabindex="-1">AI Assistant — Production Readiness Audit <a class="header-anchor" href="#ai-assistant-—-production-readiness-audit" aria-label="Permalink to &quot;AI Assistant — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-08-21</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — remediations merged; staging smoke + Central key + scheduler still required before Marketplace traffic</td></tr><tr><td><strong>Scope</strong></td><td>Billable Marketplace module <code>ai</code> catalog <strong>1.1.0</strong> + packs <code>ai-credits-1k</code> / <code>5k</code> / <code>20k</code></td></tr><tr><td><strong>Branch</strong></td><td><code>feature/ai-tools-depth-ask-elosync</code></td></tr><tr><td><strong>Companion</strong></td><td><a href="./ai">AI deployment</a> · <a href="/architecture/ai-platform">Architecture</a> · <a href="/developer-guide/ai-credits">Credits</a> · <a href="/developer-guide/ai-tools">Tools</a> · <a href="/api/tenant-v1-ai">API</a> · <a href="/user-guide/ai-assistant">User guide</a></td></tr></tbody></table><p><strong>PRs (open):</strong> Backend / Frontend / Docs on <code>feature/ai-tools-depth-ask-elosync</code></p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>EloSync AI is a <strong>billable</strong> Marketplace SKU (<code>$29/mo</code>, <code>$290/yr</code>), <strong>not</strong> default-included. Phase 1 ships Gateway orchestration over <code>laravel/ai</code>, dual-balance credit wallet, BYOK + Central keys, Ask EloSync panel, Lead Copilot, and write confirmation for <code>create_task</code>.</p><p>Catalog <strong>1.1.0</strong> adds Projects / Opportunities / Invoices <strong>read</strong> tools, Ask EloSync starter chips, numeric deep-link ids, and citation URL allowlisting (<code>isSafeRedirectPath</code>).</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>. Credit-integrity hardenings (wallet row lock, pre-provider credit ceiling, request-path <code>ensurePeriod</code>), <code>ai.manage</code> enforcement on Settings AI, and dedicated <code>throttle:ai</code> remain in place. Complete staging smoke and Central AI key + scheduler setup before production Marketplace opt-in.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Catalog billable <code>ai</code> / $29 / $290 / not default-included</td><td><strong>Pass</strong> (version <strong>1.1.0</strong>)</td></tr><tr><td>Packs depend on <code>ai</code>; grant on activate</td><td><strong>Pass</strong></td></tr><tr><td>Migrate-only register + permissions (<code>2026_08_21_010000</code>–<code>010300</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Gateway sole orchestration; <code>module:ai</code> + <code>can:ai.*</code></td><td><strong>Pass</strong></td></tr><tr><td>Encrypted / masked <code>ai_api_key</code> (Central + tenant)</td><td><strong>Pass</strong></td></tr><tr><td>Tenant isolation (<code>BelongsToTenant</code> + conversation ownership)</td><td><strong>Pass</strong></td></tr><tr><td>Write confirmation (<code>ai.confirm</code> + pending actions)</td><td><strong>Pass</strong></td></tr><tr><td>Dual wallet burn order (included → prepaid) + HTTP 402</td><td><strong>Pass</strong></td></tr><tr><td>Wallet row lock + pre-provider credit reserve</td><td><strong>Pass</strong> — <code>lockForUpdate</code> + ceiling gate</td></tr><tr><td>Lazy <code>ensurePeriod()</code> on request path</td><td><strong>Pass</strong> — chat, copilot, credits summary</td></tr><tr><td><code>ai.manage</code> enforced on Settings AI</td><td><strong>Pass</strong> — API + UI</td></tr><tr><td>AI-specific rate limits</td><td><strong>Pass</strong> — <code>throttle:ai</code> (30/min)</td></tr><tr><td>Pest AI suite</td><td><strong>Pass</strong> — Feature + Unit coverage including remediations</td></tr><tr><td>Playwright <code>test:e2e:ai</code></td><td><strong>Pass</strong> — 6/6 serial (2026-08-21 local)</td></tr><tr><td>Deploy / upgrade docs</td><td><strong>Pass</strong> — this page + <a href="./upgrade#ai-assistant-platform-100">Upgrade</a></td></tr></tbody></table><hr><h2 id="locked-decision-matrix" tabindex="-1">Locked-decision matrix <a class="header-anchor" href="#locked-decision-matrix" aria-label="Permalink to &quot;Locked-decision matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Backend</th><th>Frontend</th><th>Docs</th></tr></thead><tbody><tr><td>Packaging billable <code>ai</code> + credit packs</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Platform credits vs BYOK (BYOK does not burn EloSync credits)</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Dual wallet; burn included first</td><td>Pass</td><td>Pass (badge)</td><td>Pass</td></tr><tr><td>Write tools require confirmation</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Phase-1 tools: Leads + Tasks (+ <code>create_task</code>)</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>1.1.0 read tools: Projects + Opportunities + Invoices</td><td>Pass</td><td>Pass (starters)</td><td>Pass</td></tr><tr><td>Citation hrefs same-app only (<code>isSafeRedirectPath</code>)</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>UUID conversation / message IDs</td><td>Pass</td><td>Pass (string IDs)</td><td>Pass</td></tr><tr><td>No chatbot bolt-on / parallel auth</td><td>Pass</td><td>Pass</td><td>Pass</td></tr></tbody></table><hr><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><h3 id="closed-must-fix-conditional-go-→-go" tabindex="-1">Closed must-fix (Conditional Go → Go) <a class="header-anchor" href="#closed-must-fix-conditional-go-→-go" aria-label="Permalink to &quot;Closed must-fix (Conditional Go → Go)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>F1</td><td><strong>High</strong></td><td>Pre-call gate only checked <code>available &lt; 1</code>; burn after LLM</td><td>Pre-provider <strong>credit ceiling</strong> from prompt estimate + <code>ai_max_output_tokens</code> + tool buffer; agent <code>maxTokens()</code> capped; burn still uses actual tokens</td></tr><tr><td>F2</td><td><strong>High</strong></td><td><code>burn()</code> lacked row lock</td><td><code>lockForUpdate()</code> on wallet (and purchase ledger check) inside grant/burn/rollover transactions</td></tr><tr><td>F3</td><td><strong>High</strong></td><td><code>ensurePeriod()</code> never called</td><td>Wired on chat, Lead Copilot, and <code>GET /ai/credits</code></td></tr><tr><td>F4</td><td><strong>Medium</strong></td><td><code>ai.manage</code> unused</td><td>Settings AI update/test require <code>ai.manage</code>; UI tab gated by module + <code>ai.manage</code></td></tr></tbody></table><h3 id="_1-1-0-tools-depth-this-delivery" tabindex="-1">1.1.0 tools depth (this delivery) <a class="header-anchor" href="#_1-1-0-tools-depth-this-delivery" aria-label="Permalink to &quot;1.1.0 tools depth (this delivery)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>R5</td><td><strong>High</strong></td><td>Ask EloSync citations trusted model <code>url</code> (open redirect / phishing)</td><td><strong>Closed</strong> — <code>resolveAiReferenceHref</code> uses <code>isSafeRedirectPath</code>; unsafe urls fall back to numeric entity paths; no external AI anchors</td></tr><tr><td>L1</td><td>Low</td><td>No positive <code>availableFor</code> entitlement tests for new tools</td><td><strong>Closed</strong> — positive + module-absent registry Pest cases</td></tr><tr><td>L2</td><td>Low</td><td>Project tool happy paths skip installing <code>projects</code> in Pest</td><td><strong>Closed</strong> — <code>installOptionalCrmModules(..., [&#39;projects&#39;])</code> on project tool tests</td></tr><tr><td>L3</td><td>Low</td><td>Starter chips gate on module only, not <code>*.view</code></td><td><strong>Closed</strong> — starters require module + view permission; citations suppress unentitled modules</td></tr></tbody></table><h3 id="open-ops-ops-checklist-—-not-code-blockers" tabindex="-1">Open / ops (ops checklist — not code blockers) <a class="header-anchor" href="#open-ops-ops-checklist-—-not-code-blockers" aria-label="Permalink to &quot;Open / ops (ops checklist — not code blockers)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Owner</th></tr></thead><tbody><tr><td>O1</td><td>—</td><td><s>No dedicated throttle</s> → <strong>Closed</strong> (<code>throttle:ai</code>)</td><td>Eng</td></tr><tr><td>O2</td><td>Medium</td><td>Central <code>ai_api_key</code> must be set before platform mode works; seed leaves key null</td><td>Ops</td></tr><tr><td>O3</td><td>Medium</td><td>Sync chat on request worker — long LLM calls need adequate PHP/FPM timeouts</td><td>Ops</td></tr><tr><td>O4</td><td>Medium</td><td>Companion CI Quality Gates must pass on PRs</td><td>Eng</td></tr><tr><td>O5</td><td>Low</td><td>Architecture doc previously said <code>ai_credit_ledgers</code> (actual table <code>ai_credit_ledger</code>)</td><td>Docs (fixed)</td></tr></tbody></table><h3 id="remediated-during-delivery-e2e" tabindex="-1">Remediated during delivery / e2e <a class="header-anchor" href="#remediated-during-delivery-e2e" aria-label="Permalink to &quot;Remediated during delivery / e2e&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>R1</td><td>High</td><td>Gateway <code>Gate::authorize</code> without Auth context failed Pest</td><td>Authorize via <code>$user-&gt;can</code> / <code>Gate::forUser</code></td></tr><tr><td>R2</td><td>Medium</td><td>Frontend typed conversation IDs as <code>number</code></td><td>UUID <code>string</code> types + panel state</td></tr><tr><td>R3</td><td>Medium</td><td>Playwright <code>tab name: &#39;AI&#39;</code> matched <strong>Mail</strong></td><td>Exact tab name matching</td></tr><tr><td>R4</td><td>Medium</td><td>Billable module stayed pending after Marketplace purchase</td><td>E2E <code>entitleAiModule</code> activate path</td></tr></tbody></table><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li><strong>Backend</strong> — migrate through <code>2026_08_21_150423</code> (catalog <strong>1.1.0</strong>); confirm scheduler runs <code>ai:rollover-monthly-credits</code></li><li><strong>Central Settings → AI</strong> — enable platform AI; set encrypted <code>ai_api_key</code> + models</li><li><strong>Frontend</strong> — SPA with Ask EloSync starters, safe citations, Settings AI (<code>ai.manage</code>), Lead Copilot, Central usage</li><li><strong>Docs</strong> — including this readiness page</li><li>Staging smoke before production Marketplace opt-in</li></ol><p>Suggested merge order: <strong>Backend → Frontend → Docs</strong>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrations <code>2026_08_21_010000</code>–<code>010300</code> <strong>and</strong> <code>150423</code> (ai <strong>1.1.0</strong>) applied (no production <code>db:seed</code>)</td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Catalog rows <code>ai</code>, <code>ai-credits-1k</code>, <code>ai-credits-5k</code>, <code>ai-credits-20k</code> published; <code>ai</code> billable <strong>1.1.0</strong></td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td>Permissions <code>ai.use</code>, <code>ai.manage</code>, <code>ai.confirm</code> granted to default admin/manager maps</td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Scheduler includes <strong><code>ai:rollover-monthly-credits</code></strong> (daily, <code>withoutOverlapping</code>, <code>onOneServer</code>)</td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td>Central AI: <code>ai_enabled</code>, <code>ai_allow_platform</code> / <code>ai_allow_byok</code>, provider + <strong><code>ai_api_key</code></strong>, models, credits knobs</td><td>Ops</td><td>☐</td></tr><tr><td>6</td><td>Stable <strong><code>APP_KEY</code></strong> (decrypts stored API keys)</td><td>Ops</td><td>☐</td></tr><tr><td>7</td><td>FPM/proxy timeouts tolerate sync LLM calls</td><td>Ops</td><td>☐</td></tr><tr><td>8</td><td>Marketplace purchase → pending → payment/<code>activate</code> before entitlements</td><td>Ops</td><td>☐</td></tr><tr><td>9</td><td>Pest AI suite green in CI</td><td>Eng</td><td>☐</td></tr><tr><td>10</td><td>Playwright <code>npm run test:e2e:ai</code> green</td><td>QA</td><td>☐</td></tr><tr><td>11</td><td>F1–F4 remediations shipped in <strong>1.0.1</strong>; read-tool depth + Ask EloSync starters in <strong>1.1.0</strong></td><td>Eng</td><td>☑</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Central → Settings → AI → set key → <strong>Test AI connection</strong></li><li>Marketplace → install <strong>AI</strong> → activate (payment path or local activate)</li><li>Confirm credit badge / wallet after activation (prorated included if mid-month)</li><li>Settings → AI (<code>ai.manage</code>) → validation → save platform mode</li><li>Ask EloSync → starter chips (entitled modules) → send / graceful provider error</li><li>Ask overdue projects / pipeline summary / overdue invoices (when modules entitled)</li><li>Confirm citation chips never navigate off-app (unsafe model urls ignored)</li><li>Exhaust / zero wallet → expect <strong>402</strong> / clear UI error on platform mode</li><li>Lead detail → AI Copilot → Summarize / Next action / Draft (preview only)</li><li>Prompt a write (<code>create_task</code>) → pending action → confirm with <code>ai.confirm</code> / cancel</li><li>Optional: buy credit pack → prepaid balance increases; ledger idempotent on replay</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA (hides Ask EloSync / AI settings when module absent)</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep additive migrations</td></tr><tr><td>Module disable</td><td>Marketplace cancel / deactivate <code>ai</code> (packs require <code>ai</code>)</td></tr><tr><td>Schema</td><td>Do <strong>not</strong> roll back AI migrations without a data plan</td></tr></tbody></table><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Central <strong>AI usage</strong> page + <code>ai_usage_events</code></li><li>Platform audit events: <code>ai.chat_completed</code>, <code>ai.lead_copilot</code></li><li>HTTP <strong>402</strong> rate (credit exhaustion)</li><li>Scheduler heartbeat for <code>ai:rollover-monthly-credits</code></li><li>Provider/API errors in application logs (Nightwatch follows default exception capture)</li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Eng</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>QA</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>Ops</td><td></td><td></td><td>☐ Ready</td></tr></tbody></table><p><strong>Release decision:</strong> <strong>Go</strong> — merge companions after CI green. Complete staging smoke and Central AI key + scheduler setup before production Marketplace traffic.</p>',42)])])}const u=e(r,[["render",s]]);export{p as __pageData,u as default};
